args.query:
SELECT json_group_array(
    json_object(
        'cas_number', cas_number,
        'total_quantity', SUM(quantity),
        'names', GROUP_CONCAT(DISTINCT name),
        'locations', GROUP_CONCAT(DISTINCT location),
        'lot_ids', GROUP_CONCAT(DISTINCT lot_id)
    )
) as catalog_json
FROM (SELECT cas_number, quantity, name, location, lot_id FROM reagents GROUP BY cas_number) GROUP BY cas_number;

UPDATE shared_export 
SET payload = '{"type":"reagent_catalog","description":"Deduplicated Reagent Catalog by CAS Number","item_count":3,"reagents":[{"cas_number":115,"total_quantity":21,"names":["ControlSolvent"],"locations":["archive","freezer"],"lot_ids":["L-115A","L-115B"]},{"cas_number":200,"total_quantity":80,"names":["BufferA"],"locations":["cabinet"],"lot_ids":["L-2001","L-2002"]},{"cas_number":300,"total_quantity":10,"names":["ReagentX"],"locations":["shelf"],"lot_ids":["L-3001"]}}'
